// Generate random shift data based on current date
const generateShiftsForDate = (date) => {
  const dayOfWeek = date.getDay();
  const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
  
  // Random number of shifts (1-4 for weekdays, 1-2 for weekends)
  const numShifts = isWeekend ? Math.floor(Math.random() * 2) + 1 : Math.floor(Math.random() * 4) + 1;
  const shifts = [];
  
  // Available time slots
  const timeSlots = ['07:00', '08:00', '09:00', '10:00', '11:00', '12:00', '13:00', '14:00', '15:00', '16:00', '17:00', '18:00', '19:00', '20:00', '21:00'];
  const shiftTypes = [
    { title: 'Ca sáng', icon: 'sunny', bgColor: '#FEF7E0', iconColor: '#FFD700' },
    { title: 'Ca trưa', icon: 'sunny', bgColor: '#FCE8E6', iconColor: '#FF69B4' },
    { title: 'Ca tối', icon: 'moon', bgColor: '#E8EAF6', iconColor: '#9370DB' },
    { title: 'Ca đêm', icon: 'moon', bgColor: '#E8EAF6', iconColor: '#9370DB' },
    { title: 'Ca phụ', icon: 'time', bgColor: '#E8F5E8', iconColor: '#4CAF50' }
  ];
  
  const statuses = ['normal', 'missing', 'warning'];
  const tasks = ['Kiểm tra kho', 'Phục vụ khách', 'Dọn dẹp', 'Bảo trì', 'Kiểm tra quầy', 'Đặt lịch'];
  
  for (let i = 0; i < numShifts; i++) {
    // Random start time
    const startIndex = Math.floor(Math.random() * (timeSlots.length - 2));
    const startTime = timeSlots[startIndex];
    
    // Random duration (1-4 hours)
    const duration = Math.floor(Math.random() * 4) + 1;
    const endIndex = Math.min(startIndex + duration, timeSlots.length - 1);
    const endTime = timeSlots[endIndex];
    
    // Random shift type
    const shiftType = shiftTypes[Math.floor(Math.random() * shiftTypes.length)];
    
    // Random status
    const status = statuses[Math.floor(Math.random() * statuses.length)];
    
    // Random employees (1-4 people)
    const numEmployees = Math.floor(Math.random() * 4) + 1;
    const employees = [];
    for (let j = 0; j < numEmployees; j++) {
      employees.push({
        id: j + 1,
        name: `Nhân viên ${String.fromCharCode(65 + j)}`,
        avatar: `https://i.pravatar.cc/32?img=${j + 1}`
      });
    }
    
    shifts.push({
      id: `${date.getDate()}-${i + 1}`,
      title: shiftType.title,
      startTime: startTime,
      endTime: endTime,
      backgroundColor: shiftType.bgColor,
      iconColor: shiftType.iconColor,
      iconName: shiftType.icon,
      employees: employees,
      task: tasks[Math.floor(Math.random() * tasks.length)],
      status: status,
      ...(status === 'missing' && { missingText: 'Thiếu nv' })
    });
  }
  
  return shifts;
};

// Generate shifts for a week
const generateWeekShifts = (startDate) => {
  const shifts = {};
  for (let i = 0; i < 7; i++) {
    const date = new Date(startDate);
    date.setDate(startDate.getDate() + i);
    shifts[date.getDate()] = generateShiftsForDate(date);
  }
  return shifts;
};

// Get current week's Monday
const getCurrentWeekMonday = () => {
  const today = new Date();
  const dayOfWeek = today.getDay();
  const monday = new Date(today);
  monday.setDate(today.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));
  return monday;
};

// Generate shifts for current week and next few weeks
const currentWeekMonday = getCurrentWeekMonday();
export const weeklyShifts = generateWeekShifts(currentWeekMonday);

export const timeSlots = [
  '07:00', '08:00', '09:00', '10:00', '11:00', '12:00',
  '13:00', '14:00', '15:00', '16:00', '17:00', '18:00',
  '19:00', '20:00', '21:00', '22:00', '23:00'
];

// Helper function to get shifts for any date
export const getShiftsForDate = (date) => {
  const dayOfWeek = date.getDay();
  const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
  
  if (isWeekend) {
    return [
      {
        id: `${date.getDate()}-1`,
        title: 'Ca sáng',
        startTime: '08:00',
        endTime: '12:00',
        backgroundColor: '#FEF7E0',
        iconColor: '#FFD700',
        iconName: 'sunny',
        employees: [
          { id: 1, name: 'Nguyễn Văn A', avatar: 'https://i.pravatar.cc/32?img=1' },
          { id: 2, name: 'Trần Thị B', avatar: 'https://i.pravatar.cc/32?img=2' },
        ],
        status: 'normal'
      },
      {
        id: `${date.getDate()}-2`,
        title: 'Ca trưa',
        startTime: '12:00',
        endTime: '18:00',
        backgroundColor: '#FCE8E6',
        iconColor: '#FF69B4',
        iconName: 'sunny',
        employees: [
          { id: 3, name: 'Lê Thị C', avatar: 'https://i.pravatar.cc/32?img=3' },
        ],
        status: 'missing',
        missingText: 'Thiếu nv'
      }
    ];
  } else {
    return [
      {
        id: `${date.getDate()}-1`,
        title: 'Ca sáng',
        startTime: '07:00',
        endTime: '11:00',
        backgroundColor: '#FEF7E0',
        iconColor: '#FFD700',
        iconName: 'sunny',
        employees: [
          { id: 1, name: 'Nguyễn Văn A', avatar: 'https://i.pravatar.cc/32?img=1' },
          { id: 2, name: 'Trần Thị B', avatar: 'https://i.pravatar.cc/32?img=2' },
          { id: 3, name: 'Lê Thị C', avatar: 'https://i.pravatar.cc/32?img=3' },
        ],
        task: 'Kiểm tra kho',
        status: 'normal'
      },
      {
        id: `${date.getDate()}-2`,
        title: 'Ca trưa',
        startTime: '12:00',
        endTime: '17:00',
        backgroundColor: '#FCE8E6',
        iconColor: '#FF69B4',
        iconName: 'sunny',
        employees: [
          { id: 4, name: 'Phạm Thị D', avatar: 'https://i.pravatar.cc/32?img=4' },
          { id: 5, name: 'Hoàng Thị E', avatar: 'https://i.pravatar.cc/32?img=5' },
        ],
        task: 'Phục vụ khách',
        status: 'normal'
      },
      {
        id: `${date.getDate()}-3`,
        title: 'Ca tối',
        startTime: '17:00',
        endTime: '21:00',
        backgroundColor: '#E8EAF6',
        iconColor: '#9370DB',
        iconName: 'moon',
        employees: [
          { id: 6, name: 'Vũ Thị F', avatar: 'https://i.pravatar.cc/32?img=6' },
          { id: 7, name: 'Đặng Văn G', avatar: 'https://i.pravatar.cc/32?img=7' },
        ],
        task: 'Dọn dẹp',
        status: 'normal'
      }
    ];
  }
};
